function updateHeader(){$("#credits").textContent=state.credits.toLocaleString("pt-BR")+" CR";$("#headerFuel").textContent=Math.round(state.fuel)+" / "+shipFuel()+" u";$("#reputation").textContent=state.reputation+" / 100 · N"+unlockedContractLevel();$("#cargoBadge").textContent=state.accepted.length;const go=$("#goToCargo");if(go){const count=state.accepted.length,destination=acceptedCargo()[0]?.destination;go.disabled=!count;go.textContent=count?`Acondicionar ${count} encomenda${count>1?'s':''} para ${destination} →`:'Selecione ao menos um contrato'}}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2400)}
function rng(seed){let a=seed|0;return()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function emergencyContract(destination){if(!destination)return null;const d=DESTINATIONS[destination],mass=20+(state.boardSeed%13);return{id:`emergency-${state.boardSeed}-${destination}`,client:'Sindicato de Transporte Galático',cargo:d.emergency,destination,mass,volume:1,type:'emergency',reward:0,emergency:true}}
function unlockedContractLevel(){return Math.min(5,1+Math.floor(Math.max(0,Math.min(100,state?.reputation??25))/25))}
function contractLevelName(level){return['','REGULAR','PRIORITÁRIA','ESPECIALISTA','CONFIDENCIAL','DIPLOMÁTICA'][level]}
function contracts(){const r=rng(state.boardSeed),out=[],unlocked=unlockedContractLevel();Object.entries(DESTINATIONS).forEach(([destination,d],di)=>{const count=3+Math.floor(r()*3),distanceFactor=Math.log10(d.km/384400+1);for(let i=0;i<count;i++){const cargo=d.cargo[Math.floor(r()*d.cargo.length)],type=r()<.32?'fragile':r()<.58?'heavy':'standard',volume=type==='heavy'?2+Math.floor(r()*2):1+Math.floor(r()*2),mass=Math.round((type==='heavy'?52:14)+r()*(type==='heavy'?36:34)),level=1+Math.floor(r()*unlocked),baseReward=d.rewardBase?d.rewardBase+Math.round((mass*42+d.risk*850+r()*6000)/100)*100:Math.round((420+distanceFactor*480+mass*5+d.risk*55)/10)*10,reward=Math.round(baseReward*(1+(level-1)*.35)/10)*10;out.push({id:`${state.boardSeed}-${di}-${i}`,client:d.clients[Math.floor(r()*d.clients.length)],cargo,destination,mass,volume,type,level,reward})}});const emergency=emergencyContract(state.emergencyDestination);if(emergency)out.unshift(emergency);return out}
function nav(view){$$('.view,.nav button').forEach(e=>e.classList.remove('active'));$('#'+view).classList.add('active');const button=$(`.nav button[data-view="${view}"]`);if(button)button.classList.add('active');if(view==='cargo')renderCargo();if(['hangar','workshop','refueling','dealership'].includes(view))renderGarage()}
