function shipFuel(){const ship=SHIPS[state.activeShip];return ship.fuel+state.upgrades.tank*ship.tankStep}
function shipSlots(){return SHIPS[state.activeShip].slots}
function fuelPrice(){return 1}
function acceptedCargo(extra){return [...state.accepted,...(extra?[extra]:[])].map(id=>contracts().find(c=>c.id===id)).filter(Boolean)}
function tripFuel(list=acceptedCargo()){if(!list.length)return 0;const d=DESTINATIONS[list[0].destination],mass=list.reduce((n,c)=>n+c.mass,0);return Math.round(d.travel+mass*(1.15+d.risk*.14))}
function contractBlockReason(c){const current=acceptedCargo(),d=DESTINATIONS[c.destination],ship=SHIPS[state.activeShip];if(d.requiredTier&&ship.tier<d.requiredTier)return`Exige nave categoria ${d.requiredTier}`;if(current[0]&&current[0].destination!==c.destination)return'Destino diferente';const candidate=[...current,c];if(!current.length&&((state.landings||0)+1)%3===0){const emergency=emergencyContract(c.destination);if(emergency)candidate.push(emergency)}if(candidate.reduce((n,x)=>n+x.volume,0)>shipSlots())return'Sem espaços disponíveis';if(candidate.reduce((n,x)=>n+x.mass,0)>ship.mass+state.upgrades.hold*30*ship.tier)return'Limite de massa';if(tripFuel(candidate)>state.fuel-150)return'Combustível insuficiente';return''}
function canAdd(c){return!contractBlockReason(c)}
function decorateEmergencyCards(){$$('[data-contract^="emergency-"]').forEach(button=>{button.disabled=true;button.textContent='Obrigatória · Sem frete';const card=button.closest('.card');if(!card)return;card.classList.add('emergency-card');const tag=card.querySelector('.tags .tag');if(tag){tag.textContent='EMERGÊNCIA';tag.className='tag emergency'}const reward=[...card.querySelectorAll('p')].find(p=>p.textContent.includes('Frete pela distância'));if(reward)reward.innerHTML='Missão humanitária: <b>SEM PAGAMENTO</b>'})}
function formatDistance(km){if(km>=9461000000000){const ly=km/9461000000000;return(ly/1000000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' milhões de anos-luz'}if(km>=1000000000)return(km/1000000000).toLocaleString('pt-BR',{maximumFractionDigits:2})+' bilhão km';return km<1000000?Math.round(km/1000)+' mil km':(km/1000000).toLocaleString('pt-BR',{maximumFractionDigits:0})+' milhões km'}
function renderContracts(){const current=acceptedCargo(),locked=current[0]?.destination,dests=locked?[locked]:["Todos",...Object.keys(DESTINATIONS)];if(locked)filter=locked;$("#destinationFilter").innerHTML=dests.map(d=>`<button class="${filter===d?'active':''}" data-dest="${d}">${locked?'Destino definido: ':''}${d}</button>`).join('');$$('#destinationFilter button').forEach(b=>b.onclick=()=>{filter=b.dataset.dest;renderContracts()});$("#contractList").innerHTML=contracts().filter(c=>locked?c.destination===locked:filter==='Todos'||c.destination===filter).map(c=>{const accepted=state.accepted.includes(c.id),p=DESTINATIONS[c.destination],reason=accepted?'':contractBlockReason(c),possible=accepted||!reason,fuel=tripFuel(accepted?acceptedCargo():[...acceptedCargo(),c]);return `<article class="card ${accepted?'selected':''}" style="--planet:${p.color}"><div class="route"><div><small>${c.client}</small><h2>${c.destination}</h2></div><span class="planet">●</span></div><strong>${c.cargo}</strong><p class="lore">${p.lore}</p><div class="tags"><span class="tag ${c.type}">${c.type==='fragile'?'FRÁGIL':c.type==='heavy'?'PESADA':'PADRÃO'}</span><span class="tag">RISCO ${p.risk}/5</span><span class="tag">≈ ${formatDistance(p.km)}</span></div><div class="stats"><span>MASSA<b>${c.mass} kg</b></span><span>VOLUME<b>${c.volume} slot${c.volume>1?'s':''}</b></span><span>VIAGEM<b class="${fuel<=shipFuel()-150?'fuel-ok':'fuel-bad'}">${fuel}/${shipFuel()} u</b></span></div><p>Frete pela distância: <b>${c.reward} CR</b></p><button data-contract="${c.id}" class="${accepted?'secondary':'primary'}" ${!possible?'disabled':''}>${accepted?'Recusar contrato':possible?'Aceitar contrato':reason}</button></article>`}).join('');$$('[data-contract]').forEach(b=>b.onclick=()=>toggleContract(b.dataset.contract))}
const renderContractsCore=renderContracts;renderContracts=()=>{renderContractsCore();$$('#contractList .tag').forEach(tag=>{if(tag.textContent.startsWith('RISCO'))tag.textContent=tag.textContent.replace('/5','/8')});$$('#contractList [data-contract]').forEach(button=>{const c=contracts().find(x=>x.id===button.dataset.contract),tags=button.closest('.card')?.querySelector('.tags');if(c?.level&&tags)tags.insertAdjacentHTML('beforeend',`<span class="tag trust-level level-${c.level}">NÍVEL ${c.level} · ${contractLevelName(c.level)}</span>`)});const route=acceptedCargo(),cost=tripFuel(route),next=state.reputation>=100?'máxima':Math.ceil((state.reputation+1)/25)*25;$('#contractFuelStatus').innerHTML=`<span>Combustível no tanque: <b>${Math.round(state.fuel)} / ${shipFuel()} u</b></span><span>Confiança: <b>${state.reputation}/100 · nível ${unlockedContractLevel()}</b>${next==='máxima'?' · faixa máxima':` · próxima faixa em ${next}`}</span><span>${route.length?`Custo da rota: <b>${cost} u</b>`:`Nave categoria <b>${SHIPS[state.activeShip].tier}</b>`}</span>`}
function toggleContract(id){const c=contracts().find(x=>x.id===id);if(!c)return;if(c.emergency)return toast('Carga de emergência obrigatória para a sobrevivência da colônia.');if(!state.accepted.includes(id)){const reason=contractBlockReason(c);if(reason)return toast(reason+'.')}if(state.accepted.includes(id)){state.accepted=state.accepted.filter(x=>x!==id);state.slots=state.slots.map(x=>x===id?null:x);const paid=acceptedCargo().filter(x=>!x.emergency);if(!paid.length){state.accepted=[];state.slots=Array(shipSlots()).fill(null);state.cargoRotations={};state.emergencyDestination=null;filter='Todos'}}else{state.accepted.push(id);filter=c.destination;if(state.accepted.length===1&&((state.landings||0)+1)%3===0){state.emergencyDestination=c.destination;const emergency=emergencyContract(c.destination);state.accepted.push(emergency.id);toast('Terceira missão do ciclo: carga de emergência adicionada sem frete, em nome da sobrevivência da colônia.')}}save();renderContracts()}
function cargoFor(id){return contracts().find(c=>c.id===id)}
function cargoMetrics(){if(flight?.training)return{mass:0,used:0,com:0,vcg:0,limit:Infinity};let mass=0,moment=0,verticalMoment=0,used=0;const rows=shipSlots()/2,ship=SHIPS[state.activeShip];state.slots.forEach((id,i)=>{const c=cargoFor(id);if(c){const part=c.mass/c.volume,row=Math.floor(i/2),side=i%2?-1*-1:-1,height=rows===1?0:1.35-row/(rows-1)*2;mass+=part;moment+=part*side;verticalMoment+=part*height;used++}});return{mass,used,com:mass?moment/mass:0,vcg:mass?verticalMoment/mass:0,limit:ship.mass+state.upgrades.hold*30*ship.tier}}
function baseCargoShape(c){if(c.volume<=1)return[[0,0]];if(c.volume===2)return[[0,0],[1,0]];return[[0,0],[0,1],[1,1]]}
function cargoShape(c,rotation=0){let shape=baseCargoShape(c);for(let n=0;n<rotation%4;n++){shape=shape.map(([x,y])=>[-y,x]);const minX=Math.min(...shape.map(p=>p[0])),minY=Math.min(...shape.map(p=>p[1]));shape=shape.map(([x,y])=>[x-minX,y-minY])}return shape}
function cellsForCargo(c,start,rotation){const col=start%2,row=Math.floor(start/2),rows=shipSlots()/2,points=cargoShape(c,rotation);if(points.some(([x,y])=>col+x<0||col+x>=2||row+y<0||row+y>=rows))return null;return points.map(([x,y])=>(row+y)*2+col+x)}
function placementAnchors(){const center=(shipSlots()/2-1)/2;return Array.from({length:shipSlots()},(_,i)=>i).sort((a,b)=>Math.abs(Math.floor(a/2)-center)-Math.abs(Math.floor(b/2)-center))}
function placeCargo(id,start,rotation=state.cargoRotations[id]||0,search=false){const c=cargoFor(id);if(!c)return false;const occupied=state.slots.map((x,i)=>x&&x!==id?i:null).filter(i=>i!==null),preferred=placementAnchors(),anchors=Number.isInteger(start)?[start]:preferred;if(search&&Number.isInteger(start))anchors.push(...preferred.filter(i=>i!==start));const anchor=anchors.find(a=>{const cells=cellsForCargo(c,a,rotation);return cells&&cells.every(i=>!occupied.includes(i))});if(anchor===undefined){toast('A peça não cabe nessa posição. Gire-a ou escolha outro espaço.');return false}const cells=cellsForCargo(c,anchor,rotation);state.slots=state.slots.map(x=>x===id?null:x);cells.forEach(i=>state.slots[i]=id);state.cargoRotations[id]=rotation%4;selectedSlot=null;save();renderCargo();return true}
function rotateCargo(id){const c=cargoFor(id);if(!c||c.volume===1)return;const current=state.cargoRotations[id]||0,next=(current+1)%4,anchor=state.slots.findIndex(x=>x===id);placeCargo(id,anchor>=0?anchor:undefined,next,true)}
function removeCargo(id){state.slots=state.slots.map(x=>x===id?null:x);delete state.cargoRotations[id];selectedSlot=null;save();renderCargo()}
