let last=performance.now();function loop(now){const dt=Math.min(.033,(now-last)/1000);last=now;tickCountdown(now);if(flight&&flight.status==='flying'&&flight.fuel>0&&(keys.topLeft||keys.topRight)){const top=(keys.topLeft?1:0)-(keys.topRight?1:0);flight.angular+=top*dt*.95}applyLandingComputer(dt);update(dt);draw();drawWidePad();drawLandingGuides();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function key(e,on){const control=['KeyQ','KeyA','KeyO','KeyK'].includes(e.code);if(on&&control&&flight?.status==='ready'){beginCountdown();return}if(e.code==='KeyQ')keys.topLeft=on;if(e.code==='KeyA')keys.left=on;if(e.code==='KeyO')keys.topRight=on;if(e.code==='KeyK')keys.right=on;if(on&&e.code==='KeyR'&&flight){if(flight.training)startTraining(flight.destination);else startFlight()}}addEventListener('keydown',e=>key(e,true));addEventListener('keyup',e=>key(e,false));function touchButton(el,k){const set=v=>e=>{e.preventDefault();if(v&&flight?.status==='ready'){beginCountdown();return}keys[k]=v};el.addEventListener('pointerdown',set(true));el.addEventListener('pointerup',set(false));el.addEventListener('pointercancel',set(false));el.addEventListener('pointerleave',set(false))}touchButton($('#topLeftThruster'),'topLeft');touchButton($('#bottomLeftThruster'),'left');touchButton($('#topRightThruster'),'topRight');touchButton($('#bottomRightThruster'),'right');
function upgradeCost(k){const u=UPGRADES[k],ship=SHIPS[state.activeShip],level=state.upgrades[k]+1;if(level<=3)return Math.round(u.base*ship.upgradeScale*[1,1.4,1.85][level-1]);const nextShip=Object.values(SHIPS).find(s=>s.tier===ship.tier+1);return Math.round(u.base*(nextShip?nextShip.upgradeScale*1.08:ship.upgradeScale*2.7))}
function repairCost(){return Math.round(SHIPS[state.activeShip].repair*(100-state.condition)/100)}
